INSERT INTO settings (key, value, updated_at, updated_by) VALUES ('reply_instructions', '"You write public replies from Sun City Plumbing & Heating (plumbing, HVAC and construction in Las Cruces, NM) to Google reviews. Voice: warm, grateful, professional, plain-spoken. Thank the customer. Use the customer''s first name when it reads naturally (not every time). If employees are named, thank or credit them by first name, spelled as in the directory. Only refer to facts the customer actually mentioned; never invent details, promises, discounts, timelines or contact info. Never mention spiffs, bonuses, or that the reply is AI-written. No emojis or hashtags. Do not be defensive. For a negative or mixed review, stay calm and brief, acknowledge the experience without admitting fault, invite them to contact the office, and set needs_attention to true so a person reviews the reply. Match the reply''s length to the review''s length per the length target: short reviews get short replies, and reserve longer replies for longer reviews."', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'seed');
INSERT INTO settings (key, value, updated_at, updated_by) VALUES ('variety_warning', '"These are the last replies we posted. Do not reuse their openings, closings, sentence structures or signature phrases (for example ''We truly appreciate your trust in Sun City Plumbing & Heating''). Keep the same warm, professional voice but make this one feel fresh and different."', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'seed');
INSERT INTO settings (key, value, updated_at, updated_by) VALUES ('model', '"gpt-5.4-mini"', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'seed');
INSERT INTO settings (key, value, updated_at, updated_by) VALUES ('reasoning_effort', '"low"', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'seed');
INSERT INTO settings (key, value, updated_at, updated_by) VALUES ('recent_replies_count', '3', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'seed');
INSERT INTO settings (key, value, updated_at, updated_by) VALUES ('examples_per_call', '4', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'seed');
INSERT INTO settings (key, value, updated_at, updated_by) VALUES ('length_buckets', '[{"max_words":20,"label":"1-2 short sentences, about 15-35 words"},{"max_words":60,"label":"2-3 sentences, about 30-60 words"},{"max_words":120,"label":"3-4 sentences, about 55-90 words"},{"max_words":null,"label":"4-6 sentences, about 80-130 words"}]', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'seed');
INSERT INTO settings (key, value, updated_at, updated_by) VALUES ('analyze_rate_limit_per_hour', '30', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'seed');
INSERT INTO reply_examples (customer_name, review_text, reply_text, word_count, active, created_at) VALUES ('Steve Rogers', 'Rubin and Brian did a terrific job. Very professional, skilled, courteous and efficient. Would recommend highly to everyone!', 'Thank you so much for your kind words! We’re thrilled to hear that Ruben and Brian provided such professional and efficient service. We truly appreciate your recommendation and your trust in Sun City Plumbing & Heating.', 18, 1, strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT INTO reply_examples (customer_name, review_text, reply_text, word_count, active, created_at) VALUES ('Trevor Weiss', 'They arrived on time, were professional, and did a great job replacing the AC Unit! Fantastic work!', 'Thank you for the fantastic review! We truly appreciate your kind words and your trust in Sun City Plumbing & Heating.', 17, 1, strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT INTO reply_examples (customer_name, review_text, reply_text, word_count, active, created_at) VALUES ('Keith Risinger', 'Justin replaced our outside faucets and provided explanation of options and what to be aware of. He was very friendly and professional. I will plan on using Sun City for any future work. Thank you Justin!', 'Thanks for sharing your experience Keith! We’re glad Justin provided excellent service and guidance on your outside faucets. We appreciate your trust in Sun City Plumbing & Heating for future projects!', 36, 1, strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT INTO reply_examples (customer_name, review_text, reply_text, word_count, active, created_at) VALUES ('John Tapia', 'Malachi and Esteban were professional and very helpful!!  Sun City is a good run company.', 'Thank you, John so much for your kind review! Don’t hesitate to reach out if you need anything in the future!', 15, 1, strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT INTO reply_examples (customer_name, review_text, reply_text, word_count, active, created_at) VALUES ('Mary Spence', 'I very rarely write reviews, but Sun City has earned these five stars for sure. We needed an air conditioner repair right in the middle of summer (everyone in Las Cruces dreads that). I got impatient and called another company that would come out the next day. They  told me to replace the whole system (only 3.5 years old) after less than 30 seconds looking at it.
